import {translate,getLocale} from './i18n.js';
// All source-record fields are retained, including null values and every rating / allowance.
export const CERTIFICATE_LABELS={NatAuth:'Autorità nazionale',BIN:'Identificativo BIN',CertNo:'Numero certificato',RefNo:'Riferimento ORC',SailNo:'Numero velico',YachtName:'Nome della barca',Class:'Modello / classe',Builder:'Cantiere',Designer:'Progettista',Club:'Circolo',C_Type:'Tipo di certificato',Family:'Famiglia ORC',Division:'Divisione',IssueDate:'Data di emissione',Dspl_Sailing:'Dislocamento in navigazione',Dspl_Measurement:'Dislocamento di stazza',WSS:'Superficie bagnata',Area_Main:'Area randa',Area_Jib:'Area vela di prua',Area_Sym:'Area spinnaker simmetrico',Area_Asym:'Area asimmetrico / gennaker',Age_Year:'Anno di costruzione / età',CrewWT:'Peso equipaggio',LOA:'Lunghezza fuori tutto',IMSL:'Lunghezza IMS',Draft:'Pescaggio',MB:'Baglio massimo',Dynamic_Allowance:'Abbuono dinamico',CDL:'Class Division Length',metric:'Unità metriche',GPH:'General Purpose Handicap',ILCWA:'ILCWA',APHD:'All Purpose · Time on Distance',APHT:'All Purpose · Time on Time',TMF_Inshore:'Time multiplier · Inshore',TMF_Offshore:'Time multiplier · Offshore',OSN:'Offshore Single Number'};
const UNITS={LOA:'m',IMSL:'m',Draft:'m',MB:'m',Dspl_Sailing:'kg',Dspl_Measurement:'kg',CrewWT:'kg',WSS:'m²',Area_Main:'m²',Area_Jib:'m²',Area_Sym:'m²',Area_Asym:'m²',GPH:'s/NM',APHD:'s/NM'};
const BASIC=new Set(['NatAuth','BIN','CertNo','RefNo','SailNo','YachtName','Class','Builder','Designer','Club','C_Type','Family','Division','IssueDate','Age_Year','CrewWT','LOA','IMSL','Draft','MB','Dspl_Sailing','Dspl_Measurement','WSS','Dynamic_Allowance','CDL','metric']);
const SAILS=new Set(['Area_Main','Area_Jib','Area_Sym','Area_Asym']);
export const escapeCertificateHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let bundlePromise;
export async function loadCertificate(id){if(!bundlePromise)bundlePromise=fetch(new URL('./data/ita-certificates.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Dati del certificato non disponibili.');return r.json();}).then(d=>{if(!d.records||!Array.isArray(d.ScoringOptions))throw Error('Archivio certificati non valido.');return d;}).catch(e=>{bundlePromise=null;throw e;});const bundle=await bundlePromise,record=bundle.records[id];if(!record)throw Error('Certificato non presente nel file.');return{record,scoring:bundle.ScoringOptions,countries:bundle.Countries,source:bundle.source};}
export function flattenCertificate(record,prefix=''){return Object.entries(record).flatMap(([key,value])=>{const path=prefix?prefix+'.'+key:key;return value!==null&&typeof value==='object'&&!Array.isArray(value)?flattenCertificate(value,path):[{key:path,value}];});}
function labelFor(key,meta){if(CERTIFICATE_LABELS[key])return CERTIFICATE_LABELS[key];if(key.startsWith('Allowances.')){const k=key.slice(11);return({WindSpeeds:'Intensità vento reale',WindAngles:'Angoli tabulati',Beat:'Bolina · tempo di VMG',Run:'Poppa · tempo di VMG',BeatAngle:'Angolo ottimale di bolina',GybeAngle:'Angolo ottimale di poppa'}[k]||(/^R\d+$/.test(k)?`Tempo a ${k.slice(1)}°`:k));}const option=meta?.scoring?.find(o=>o.Fieldname===key);return option?`${option.Name} · ${option.CountryId} · ${option.Kind}`:key;}
export function certificateValue(value){if(value===null)return translate('Non indicato');if(typeof value==='boolean')return value?translate('Sì'):'No';if(Array.isArray(value))return value.map(certificateValue).join(' · ');if(typeof value==='number')return value.toLocaleString(getLocale(),{maximumFractionDigits:8,useGrouping:false});return String(value);}
export function certificateFields(record,meta,section='all',query=''){const q=query.trim().toLocaleLowerCase('it');return flattenCertificate(record).map(row=>({...row,label:translate(labelFor(row.key,meta)),unit:UNITS[row.key]||((meta?.scoring?.find(o=>o.Fieldname===row.key)?.Kind==='TOD')?'s/NM':'')})).filter(row=>{const root=row.key.split('.')[0],inSection=section==='all'||(section==='overview'&&BASIC.has(root))||(section==='sails'&&SAILS.has(root))||(section==='polar'&&root==='Allowances')||(section==='ratings'&&!BASIC.has(root)&&!SAILS.has(root)&&root!=='Allowances');return inSection&&(!q||`${row.key} ${row.label} ${certificateValue(row.value)}`.toLocaleLowerCase('it').includes(q));});}
export function certificateTable(record,meta,section,query=''){const rows=certificateFields(record,meta,section,query),e=escapeCertificateHTML;if(!rows.length)return '<p class="certificate-empty">Nessun campo corrisponde alla ricerca.</p>';if(section==='polar'&&!query){const a=record.Allowances,winds=a?.WindSpeeds||[];return `<p class="certificate-unit-note">Tempi originali in s/NM; Beat e Run sono riferiti alla VMG. Gli angoli sono in gradi.</p><div class="certificate-table-scroll"><table class="certificate-polar"><thead><tr><th>Dato / TWS</th>${winds.map(w=>`<th>${e(w)} kn</th>`).join('')}</tr></thead><tbody>${rows.filter(r=>!['Allowances.WindSpeeds','Allowances.WindAngles'].includes(r.key)).map(r=>`<tr data-cert-key="${e(r.key)}"><th>${e(r.label)}<small>${e(r.key)}</small></th>${(Array.isArray(r.value)?r.value:[r.value]).map(v=>`<td>${e(certificateValue(v))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="certificate-unit-note">Angoli tabulati: ${e((a?.WindAngles||[]).join('°, '))}°. Le tabelle DW/CR/WL sono tempi aggregati di percorso.</p>`;}return `<table class="certificate-fields"><tbody>${rows.map(r=>`<tr data-cert-key="${e(r.key)}"><th>${e(r.label)}<small>${e(r.key)}</small></th><td>${e(certificateValue(r.value))}${r.value!==null&&r.unit?` <small>${e(r.unit)}</small>`:''}</td></tr>`).join('')}</tbody></table>`;}
